# Section mapping from readelf:
# .text: VMA=0x401100, file_off=0x1100
# .rodata: VMA=0x47c000, file_off=0x7c000  
# .data: VMA=0x4a80c0, file_off=0xa70c0

# The code references addresses like 0x4aace8, 0x4aace0 etc. which are in .data section
# Let's compute file offsets for those addresses
section_bases = {
    0x401100: 0x1100,   # .text
    0x47c000: 0x7c000,  # .rodata
    0x4a80c0: 0xa70c0,  # .data
}

# Addresses from disassembly comments (the # after the instruction)
